     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Todo dinheiro é arredondado para centavos, meio para o par, a cada passo. */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal v) {
    16	        return v.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static BigDecimal of(String v) {
    20	        return round(new BigDecimal(v));
    21	    }
    22	
    23	    public static BigDecimal percent(BigDecimal base, int pct) {
    24	        return round(base.multiply(BigDecimal.valueOf(pct)).divide(BigDecimal.valueOf(100)));
    25	    }
    26	
    27	    /** R$ 1.234,56 */
    28	    public static String brl(BigDecimal v) {
    29	        DecimalFormatSymbols sym = new DecimalFormatSymbols(Locale.ROOT);
    30	        sym.setDecimalSeparator(',');
    31	        sym.setGroupingSeparator('.');
    32	        DecimalFormat f = new DecimalFormat("#,##0.00", sym);
    33	        f.setRoundingMode(RoundingMode.HALF_EVEN);
    34	        return "R$ " + f.format(round(v));
    35	    }
    36	}
