     8	/**
     9	 * Um plano de tarifa: define quem pode usá-lo, como o preço é calculado e quanto
    10	 * é devolvido no cancelamento. Um plano novo é uma nova implementação registrada
    11	 * em {@link RatePlans}; nada mais precisa mudar.
    12	 */
    13	public interface RatePlan {
    14	
    15	    /** Dados da reserva que os planos precisam para decidir e calcular. */
    16	    record Booking(RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {}
    17	
    18	    /** Soma das diárias e desconto, já arredondados. */
    19	    record Price(BigDecimal subtotal, BigDecimal discount) {
    20	        public BigDecimal total() {
    21	            return subtotal.subtract(discount);
    22	        }
    23	    }
    24	
    25	    String code();
    26	
    27	    /** Lança ApiException (400 INVALID_REQUEST) se o plano não puder ser usado nesta reserva. */
    28	    default void validate(Booking booking) {}
    29	
    30	    /** @param nightsSum soma das diárias (com alta temporada) já arredondada */
    31	    Price price(Booking booking, BigDecimal nightsSum);
    32	
    33	    /** Valor devolvido no cancelamento, dado o que foi pago. */
    34	    BigDecimal refund(BigDecimal amountPaid);
    35	
    36	    /** Código da empresa a guardar na reserva (só o convênio usa). */
