     9	
    10	public class Db implements AutoCloseable {
    11	    public interface Work<T> {
    12	        T run(Connection c) throws SQLException;
    13	    }
    14	
    15	    private final HikariDataSource ds;
    16	
    17	    public Db(String url, String user, String password) {
    18	        HikariConfig cfg = new HikariConfig();
    19	        cfg.setJdbcUrl(url);
    20	        cfg.setUsername(user);
    21	        cfg.setPassword(password);
    22	        cfg.setMaximumPoolSize(10);
    23	        cfg.setInitializationFailTimeout(-1); // não falha na criação; tentamos conectar em init()
    24	        this.ds = new HikariDataSource(cfg);
    25	    }
    26	
    27	    /** Espera o banco ficar disponível e cria o que faltar. */
    28	    public void init() {
    29	        long deadline = System.currentTimeMillis() + 90_000;
    30	        while (true) {
    31	            try {
    32	                tx(c -> {
    33	                    try (Statement s = c.createStatement()) {
    34	                        // evita corrida se duas instâncias subirem juntas
    35	                        s.execute("SELECT pg_advisory_xact_lock(7070001)");
    36	                        for (String sql : SCHEMA) {
    37	                            s.execute(sql);
    38	                        }
    39	                    }
    40	                    return null;
    41	                });
    42	                return;
    43	            } catch (RuntimeException e) {
    44	                if (System.currentTimeMillis() > deadline) {
    45	                    throw e;
    46	                }
    47	                System.err.println("Aguardando o banco: " + e.getMessage());
    48	                try {
    49	                    Thread.sleep(2000);
    50	                } catch (InterruptedException ie) {
    51	                    Thread.currentThread().interrupt();
    52	                    throw e;
    53	                }
    54	            }
    55	        }
    56	    }
    57	
    58	    public <T> T tx(Work<T> work) {
    59	        try (Connection c = ds.getConnection()) {
    60	            c.setAutoCommit(false);
    61	            try {
    62	                T result = work.run(c);
    63	                c.commit();
    64	                return result;
    65	            } catch (Throwable t) {
    66	                c.rollback();
    67	                throw t;
    68	            }
    69	        } catch (SQLException e) {
    70	            throw new IllegalStateException(e.getMessage(), e);
    71	        }
    72	    }
    73	
    74	    @Override
    75	    public void close() {
    76	        ds.close();
    77	    }
