     8	
     9	public final class Pricing {
    10	    private Pricing() {}
    11	
    12	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
    13	    public static boolean isHighSeason(LocalDate night) {
    14	        Month m = night.getMonth();
    15	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    16	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    17	    }
    18	
    19	    public static BigDecimal nightPrice(BigDecimal dailyRate, LocalDate night) {
    20	        return isHighSeason(night) ? Money.percent(dailyRate, 120) : Money.round(dailyRate);
    21	    }
    22	
    23	    public static BigDecimal nightsSum(BigDecimal dailyRate, LocalDate checkIn, LocalDate checkOut) {
    24	        BigDecimal sum = Money.ZERO;
    25	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    26	            sum = Money.round(sum.add(nightPrice(dailyRate, d)));
    27	        }
    28	        return sum;
    29	    }
    30	
    31	    public static RatePlan.Price price(RatePlan plan, RatePlan.Booking booking, BigDecimal dailyRate) {
    32	        BigDecimal sum = nightsSum(dailyRate, booking.checkIn(), booking.checkOut());
    33	        return plan.price(booking, sum);
    34	    }
    35	
    36	}
