    10	public final class RequestParser {
    11	    private static final ObjectMapper MAPPER = new ObjectMapper();
    12	
    13	    private RequestParser() {}
    14	
    15	    public static ReservationService.NewReservation parseNewReservation(String body) {
    16	        JsonNode n;
    17	        try {
    18	            n = MAPPER.readTree(body == null ? "" : body);
    19	        } catch (Exception e) {
    20	            throw ApiException.invalid("O corpo não é um JSON válido.");
    21	        }
    22	        if (n == null || !n.isObject()) {
    23	            throw ApiException.invalid("O corpo deve ser um objeto JSON.");
    24	        }
    25	        int room = integer(n, "roomNumber");
    26	        String name = text(n, "guestName");
    27	        String email = text(n, "guestEmail");
    28	        String cpf = text(n, "guestCpf");
    29	        LocalDate in = date(n, "checkIn");
    30	        LocalDate out = date(n, "checkOut");
    31	        int guests = integer(n, "guests");
    32	        String plan = text(n, "ratePlan");
    33	        if (!out.isAfter(in)) {
    34	            throw ApiException.invalid("A saída deve ser depois da entrada.");
    35	        }
    36	        if (guests < 1) {
    37	            throw ApiException.invalid("É preciso pelo menos um hóspede.");
    38	        }
    39	        JsonNode cc = n.get("companyCode");
    40	        String company = cc != null && cc.isTextual() ? cc.asText().trim() : null;
    41	        return new ReservationService.NewReservation(room, name, email, cpf, in, out, guests, plan, company);
    42	    }
    43	
    44	    public static LocalDate parseDate(String s) {
    45	        try {
    46	            return LocalDate.parse(s == null ? "" : s);
    47	        } catch (DateTimeParseException e) {
    48	            throw ApiException.invalid("Data inválida; use o formato AAAA-MM-DD.");
    49	        }
    50	    }
    51	
    52	    public static YearMonth parseMonth(String s) {
    53	        try {
    54	            return YearMonth.parse(s == null ? "" : s);
    55	        } catch (DateTimeParseException e) {
    56	            throw ApiException.invalid("Mês inválido; use o formato AAAA-MM.");
    57	        }
    58	    }
    59	
    60	    private static String text(JsonNode n, String field) {
    61	        JsonNode v = n.get(field);
    62	        if (v == null || !v.isTextual() || v.asText().isBlank()) {
    63	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
    64	        }
    65	        return v.asText().trim();
    66	    }
    67	
    68	    private static int integer(JsonNode n, String field) {
    69	        JsonNode v = n.get(field);
    70	        if (v == null || !v.isIntegralNumber() || !v.canConvertToInt()) {
    71	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
    72	        }
    73	        return v.asInt();
    74	    }
