    56	    public List<Message> messages() {
    57	        return db.tx(c -> {
    58	            List<Message> out = new ArrayList<>();
    59	            try (PreparedStatement ps = c.prepareStatement(
    60	                    "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
    61	                 ResultSet rs = ps.executeQuery()) {
    62	                while (rs.next()) {
    63	                    out.add(new Message(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4), rs.getString(5)));
    64	                }
    65	            }
    66	            return out;
    67	        });
    68	    }
