    70	    // ---------- operações ----------
    71	
    72	    public Reservation create(NewReservation n) {
    73	        return db.tx(c -> {
    74	            Room room = findRoom(c, n.roomNumber(), true); // trava o quarto: serializa reservas concorrentes
    75	            if (n.guests() > room.capacity()) {
    76	                throw new ApiException(422, "CAPACITY_EXCEEDED",
    77	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " pessoas.");
