    79	            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(n.checkIn(), n.checkOut());
    80	            RatePlan plan = RatePlans.get(n.ratePlan());
    81	            RatePlan.Booking booking = new RatePlan.Booking(room.type(), n.checkIn(), n.checkOut(), nights, n.companyCode());
    82	            plan.validate(booking);
    83	            RatePlan.Price price = Pricing.price(plan, booking, room.nightlyRate());
    84	
    85	            try (PreparedStatement ps = c.prepareStatement(
    86	                    "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    87	                            + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    88	                ps.setInt(1, room.number());
    89	                ps.setDate(2, Date.valueOf(n.checkOut()));
    90	                ps.setDate(3, Date.valueOf(n.checkIn()));
