    95	                    }
    96	                }
    97	            }
    98	
    99	            try (PreparedStatement ps = c.prepareStatement(
   100	                    "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
   101	                            + "guests, rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid) "
   102	                            + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDING',0) RETURNING id")) {
   103	                ps.setInt(1, room.number());
   104	                ps.setString(2, n.guestName());
   105	                ps.setString(3, n.guestEmail());
   106	                ps.setString(4, n.guestCpf());
   107	                ps.setDate(5, Date.valueOf(n.checkIn()));
   108	                ps.setDate(6, Date.valueOf(n.checkOut()));
   109	                ps.setInt(7, n.guests());
   110	                ps.setString(8, plan.code());
   111	                ps.setString(9, plan.companyCodeToStore(booking));
   112	                ps.setInt(10, nights);
   113	                ps.setBigDecimal(11, price.subtotal());
   114	                ps.setBigDecimal(12, price.discount());
   115	                ps.setBigDecimal(13, price.total());
   116	                try (ResultSet rs = ps.executeQuery()) {
   117	                    rs.next();
   118	                    return load(c, rs.getLong(1), false);
   119	                }
   120	            }
   121	        });
   122	    }
