   124	    public Reservation confirm(long id) {
   125	        return db.tx(c -> {
   126	            Reservation r = load(c, id, true);
   127	            requireStatus(r, "confirmar", Status.PENDING);
   128	            update(c, id, Status.CONFIRMED, r.total(), null);
   129	            Reservation confirmed = load(c, id, false);
   130	            Room room = findRoom(c, r.roomNumber(), false);
   131	            try (PreparedStatement ps = c.prepareStatement(
   132	                    "INSERT INTO messages (channel, recipient, subject, body) VALUES ('EMAIL', ?, ?, ?)")) {
   133	                ps.setString(1, confirmed.guestEmail());
   134	                ps.setString(2, "Reserva confirmada - Pousada Maré Alta");
   135	                ps.setString(3, Receipt.confirmationEmail(confirmed, room));
   136	                ps.executeUpdate();
   137	            }
   138	            return confirmed;
   139	        });
