   142	    public Reservation cancel(long id) {
   143	        return db.tx(c -> {
   144	            Reservation r = load(c, id, true);
   145	            requireStatus(r, "cancelar", Status.PENDING, Status.CONFIRMED);
   146	            BigDecimal refund = RatePlans.get(r.ratePlan()).refund(r.amountPaid());
   147	            update(c, id, Status.CANCELLED, r.amountPaid(), refund);
   148	            return load(c, id, false);
   149	        });
   150	    }
   151	
   152	    public Reservation checkIn(long id) {
   153	        return db.tx(c -> {
   154	            Reservation r = load(c, id, true);
   155	            requireStatus(r, "fazer check-in de", Status.CONFIRMED);
   156	            update(c, id, Status.CHECKED_IN, r.amountPaid(), null);
   157	            return load(c, id, false);
   158	        });
   159	    }
   160	
   161	    public Reservation checkOut(long id) {
   162	        return db.tx(c -> {
   163	            Reservation r = load(c, id, true);
   164	            requireStatus(r, "fazer check-out de", Status.CHECKED_IN);
   165	            update(c, id, Status.CHECKED_OUT, r.amountPaid(), null);
   166	            return load(c, id, false);
   167	        });
   168	    }
   169	
   170	    // ---------- relatórios ----------
   171	
   172	    public String occupancyCsv(LocalDate date) {
   173	        return db.tx(c -> {
   174	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
   175	            int occupied = 0;
   176	            try (PreparedStatement ps = c.prepareStatement(
   177	                    "SELECT r.room_number, m.type, r.id, r.check_in, r.check_out FROM reservations r "
   178	                            + "JOIN rooms m ON m.number = r.room_number "
   179	                            + "WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
   180	                            + "AND r.check_in <= ? AND r.check_out > ? ORDER BY r.room_number, r.id")) {
   181	                ps.setDate(1, Date.valueOf(date));
   182	                ps.setDate(2, Date.valueOf(date));
   183	                try (ResultSet rs = ps.executeQuery()) {
   184	                    while (rs.next()) {
   185	                        occupied++;
   186	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',')
   187	                                .append(rs.getLong(3)).append(',').append(rs.getDate(4).toLocalDate()).append(',')
   188	                                .append(rs.getDate(5).toLocalDate()).append('\n');
   189	                    }
   190	                }
   191	            }
   192	            int total;
   193	            try (PreparedStatement ps = c.prepareStatement("SELECT count(*) FROM rooms");
   194	                 ResultSet rs = ps.executeQuery()) {
   195	                rs.next();
   196	                total = rs.getInt(1);
   197	            }
   198	            return sb.append("total,").append(occupied).append('/').append(total).append('\n').toString();
   199	        });
   200	    }
   201	
   202	    public String revenueCsv(YearMonth month) {
   203	        return db.tx(c -> {
   204	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   205	            BigDecimal sum = Money.ZERO;
   206	            try (PreparedStatement ps = c.prepareStatement(
   207	                    "SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0) AS amount "
   208	                            + "FROM reservations WHERE check_in >= ? AND check_in < ? "
   209	                            + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id")) {
   210	                ps.setDate(1, Date.valueOf(month.atDay(1)));
   211	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
   212	                try (ResultSet rs = ps.executeQuery()) {
   213	                    while (rs.next()) {
   214	                        BigDecimal amount = Money.round(rs.getBigDecimal(6));
   215	                        sum = sum.add(amount);
   216	                        sb.append(rs.getLong(1)).append(',').append(rs.getInt(2)).append(',')
   217	                                .append(rs.getDate(3).toLocalDate()).append(',').append(rs.getDate(4).toLocalDate())
   218	                                .append(',').append(rs.getString(5)).append(',').append(amount.toPlainString()).append('\n');
   219	                    }
   220	                }
   221	            }
   222	            return sb.append("total,").append(sum.toPlainString()).append('\n').toString();
   223	        });
   224	    }
