   226	    // ---------- internos ----------
   227	
   228	    private static void requireStatus(Reservation r, String action, Status... allowed) {
   229	        for (Status s : allowed) {
   230	            if (r.status() == s) {
   231	                return;
   232	            }
   233	        }
   234	        throw ApiException.notAllowed("Não é possível " + action + " uma reserva com situação " + r.status() + ".");
   235	    }
   236	
   237	    private static void update(Connection c, long id, Status status, BigDecimal paid, BigDecimal refund) throws SQLException {
   238	        try (PreparedStatement ps = c.prepareStatement(
   239	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
   240	            ps.setString(1, status.name());
   241	            ps.setBigDecimal(2, paid);
   242	            ps.setBigDecimal(3, refund);
   243	            ps.setLong(4, id);
   244	            ps.executeUpdate();
   245	        }
   246	    }
   247	
   248	    private static Room findRoom(Connection c, int number, boolean lock) throws SQLException {
   249	        try (PreparedStatement ps = c.prepareStatement(
   250	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?" + (lock ? " FOR UPDATE" : ""))) {
   251	            ps.setInt(1, number);
   252	            try (ResultSet rs = ps.executeQuery()) {
   253	                if (!rs.next()) {
   254	                    throw new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + number + " não existe.");
   255	                }
   256	                return room(rs);
   257	            }
   258	        }
   259	    }
   260	
   261	    private static Room room(ResultSet rs) throws SQLException {
   262	        return new Room(rs.getInt(1), RoomType.valueOf(rs.getString(2)), rs.getInt(3), Money.round(rs.getBigDecimal(4)));
   263	    }
   264	
   265	    private static Reservation load(Connection c, long id, boolean lock) throws SQLException {
   266	        try (PreparedStatement ps = c.prepareStatement(
   267	                "SELECT " + RES_COLS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
   268	            ps.setLong(1, id);
   269	            try (ResultSet rs = ps.executeQuery()) {
   270	                if (!rs.next()) {
   271	                    throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe.");
   272	                }
   273	                BigDecimal refund = rs.getBigDecimal(17);
   274	                return new Reservation(rs.getLong(1), rs.getInt(2), rs.getString(3), rs.getString(4), rs.getString(5),
   275	                        rs.getDate(6).toLocalDate(), rs.getDate(7).toLocalDate(), rs.getInt(8), rs.getString(9),
   276	                        rs.getString(10), rs.getInt(11), Money.round(rs.getBigDecimal(12)), Money.round(rs.getBigDecimal(13)),
   277	                        Money.round(rs.getBigDecimal(14)), Status.valueOf(rs.getString(15)),
   278	                        Money.round(rs.getBigDecimal(16)), refund == null ? null : Money.round(refund));
   279	            }
   280	        }
   281	    }
