     1	package br.com.marealta;
     2	
     3	import br.com.marealta.plan.RatePlan;
     4	import br.com.marealta.plan.RatePlans;
     5	import org.junit.jupiter.api.Test;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	
    10	import static org.junit.jupiter.api.Assertions.*;
    11	
    12	class PricingTest {
    13	    private static final BigDecimal STD = Money.of("249.90");
    14	    private static final BigDecimal DLX = Money.of("389.90");
    15	
    16	    private RatePlan.Price price(String plan, RoomType t, BigDecimal rate, String in, String out, String company) {
    17	        LocalDate i = LocalDate.parse(in), o = LocalDate.parse(out);
    18	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(i, o);
    19	        RatePlan p = RatePlans.get(plan);
    20	        RatePlan.Booking b = new RatePlan.Booking(t, i, o, nights, company);
    21	        p.validate(b);
    22	        return Pricing.price(p, b, rate);
    23	    }
    24	
    25	    @Test
    26	    void highSeasonBoundaries() {
    27	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-12-14")));
    28	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-12-15")));
    29	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2028-02-29")));
    30	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-03-01")));
    31	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-07-31")));
    32	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-08-01")));
    33	    }
    34	
    35	    @Test
    36	    void standardHighSeason() {
    37	        var p = price("STANDARD", RoomType.STANDARD, STD, "2027-07-10", "2027-07-12", null);
    38	        assertEquals(Money.of("599.76"), p.total());
    39	    }
    40	
    41	    @Test
    42	    void corporate() {
    43	        var p = price("CORPORATE", RoomType.DELUXE, DLX, "2027-03-10", "2027-03-12", "TECNOSUL");
    44	        assertEquals("779.80", p.subtotal().toPlainString());
    45	        assertEquals("93.58", p.discount().toPlainString());
    46	        assertEquals("686.22", p.total().toPlainString());
    47	    }
    48	
    49	    @Test
    50	    void corporateRequiresKnownCompany() {
    51	        assertThrows(ApiException.class, () -> price("CORPORATE", RoomType.DELUXE, DLX, "2027-03-10", "2027-03-12", null));
    52	        assertThrows(ApiException.class, () -> price("CORPORATE", RoomType.DELUXE, DLX, "2027-03-10", "2027-03-12", "ACME"));
    53	    }
    54	
    55	    @Test
    56	    void weekendPackage() {
    57	        var p = price("WEEKEND_PACKAGE", RoomType.DELUXE, DLX, "2027-03-12", "2027-03-14", null);
    58	        assertEquals("820.00", p.total().toPlainString());
    59	        assertEquals("410.00", RatePlans.get("WEEKEND_PACKAGE").refund(p.total()).toPlainString());
    60	        // preço fechado mesmo na alta temporada
    61	        assertEquals("520.00", price("WEEKEND_PACKAGE", RoomType.STANDARD, STD, "2027-07-09", "2027-07-11", null).total().toPlainString());
    62	        assertThrows(ApiException.class, () -> price("WEEKEND_PACKAGE", RoomType.DELUXE, DLX, "2027-03-13", "2027-03-15", null));
    63	        assertThrows(ApiException.class, () -> price("WEEKEND_PACKAGE", RoomType.DELUXE, DLX, "2027-03-12", "2027-03-15", null));
    64	    }
    65	
    66	    @Test
    67	    void longStay() {
    68	        var p = price("LONG_STAY", RoomType.STANDARD, STD, "2027-03-01", "2027-03-08", null);
    69	        assertEquals("1749.30", p.subtotal().toPlainString());
    70	        assertEquals("174.93", p.discount().toPlainString());
    71	        assertEquals("1574.37", p.total().toPlainString());
    72	        assertThrows(ApiException.class, () -> price("LONG_STAY", RoomType.STANDARD, STD, "2027-03-01", "2027-03-07", null));
    73	    }
    74	
    75	    @Test
    76	    void refunds() {
    77	        BigDecimal paid = Money.of("100.00");
    78	        assertEquals(paid, RatePlans.get("STANDARD").refund(paid));
    79	        assertEquals(Money.ZERO, RatePlans.get("NON_REFUNDABLE").refund(paid));
    80	        assertEquals(paid, RatePlans.get("CORPORATE").refund(paid));
    81	        assertEquals(paid, RatePlans.get("LONG_STAY").refund(paid));
    82	    }
    83	
    84	    @Test
    85	    void formatting() {
    86	        assertEquals("R$ 1.234,56", Money.brl(Money.of("1234.56")));
    87	        assertEquals("R$ 0,00", Money.brl(Money.ZERO));
    88	        assertEquals(Money.of("0.12"), Money.round(new BigDecimal("0.125")));
    89	    }
    90	}
